/// <summary>
/// COC extension for SalesAgreementLineEntity to support METCategoryHierarchyName on import rows.
/// </summary>
[ExtensionOf(tableStr(SalesAgreementLineEntity))]
final class METSalesAgreementLineEntity_Extension
{
}

Method.Source:
/// <summary>
/// COC extension for SalesAgreementLineEntity to support METCategoryHierarchyName on import rows.
/// </summary>
/// <param name = "_entityCtx"></param>
/// <param name = "_dataSourceCtx"></param>
/// <returns></returns>
public Common findEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    Common ret;

    ret = next findEntityDataSource(_entityCtx, _dataSourceCtx);

    ///Check if the data source is SalesAgreementLineEntity and the DefaultAgreementLineType is METVendorCategoryProductVolume, 
    ///then find the category based on RetailSpecialGroup hierarchy role.
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(SalesAgreementLineEntity, EcoResCategory_SalesCategory))
    {
        if (SalesAgreementHeader::findAgreementId(this.SalesAgreementId).DefaultAgreementLineType == CommitmentType::METVendorCategoryProductVolume)
        {
            EcoResCategoryHierarchy     ecoResCategoryHierarchy;
            EcoResCategoryHierarchyRole ecoResCategoryHierarchyRole;

            select firstonly1 ecoResCategoryHierarchy
                join ecoResCategoryHierarchyRole
                where ecoResCategoryHierarchyRole.CategoryHierarchy == ecoResCategoryHierarchy.RecId
                && ecoResCategoryHierarchyRole.NamedCategoryHierarchyRole == EcoResCategoryNamedHierarchyRole::RetailSpecialGroup;

            if (ecoResCategoryHierarchy.RecId)
            {
                ret = EcoResCategory::findByName(this.SalesProductCategoryName, ecoResCategoryHierarchy.RecId);
            }
        }
    }

    return ret;
}
